starter_files./etc/nginx/conf.d/default.conf:
# Managed by the panel's Dify recipe (RC-19). Written once at install and never
# overwritten, so edits here survive redeploys; restart the stack to apply them.
# Pre-rendered from Dify 1.17.1 docker/nginx/conf.d/default.conf.template with
# NGINX_PORT=80, NGINX_SERVER_NAME=_ and NGINX_CLIENT_MAX_BODY_SIZE=100M. The
# /socket.io/ location (collaboration profile) and the HTTPS/ACME blocks are
# left out: the panel's own nginx terminates HTTPS in front of this one.

server {
    listen 80;
    server_name _;
    resolver 127.0.0.11 valid=30s ipv6=off;
    client_max_body_size 100M;

    location /console/api {
      set $api_upstream api:5001;
      proxy_pass http://$api_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /api {
      set $api_upstream api:5001;
      proxy_pass http://$api_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /v1 {
      set $api_upstream api:5001;
      proxy_pass http://$api_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /openapi {
      set $api_upstream api:5001;
      proxy_pass http://$api_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /files {
      set $api_upstream api:5001;
      proxy_pass http://$api_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /explore {
      set $web_upstream web:3000;
      proxy_pass http://$web_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /e/ {
      set $plugin_daemon_upstream plugin_daemon:5002;
      proxy_pass http://$plugin_daemon_upstream;
      proxy_set_header Dify-Hook-Url $http_x_forwarded_proto://$host$request_uri;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location / {
      set $web_upstream web:3000;
      proxy_pass http://$web_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /mcp {
      set $api_upstream api:5001;
      proxy_pass http://$api_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }

    location /triggers {
      set $api_upstream api:5001;
      proxy_pass http://$api_upstream;
      include /etc/nginx/conf.d/dify-proxy.inc;
    }
}

starter_files./etc/nginx/conf.d/dify-proxy.inc:
# Managed by the panel's Dify recipe (RC-19); included by default.conf.
# Pre-rendered from Dify 1.17.1 docker/nginx/proxy.conf.template with
# NGINX_PROXY_READ_TIMEOUT and NGINX_PROXY_SEND_TIMEOUT at 3600s. The panel's
# nginx in front already set X-Forwarded-For and X-Forwarded-Proto (https), so
# they are passed through rather than rewritten to this hop's plain HTTP; the
# API trusts one proxy hop (RESPECT_XFORWARD_HEADERS_ENABLED).

proxy_set_header Host $host;
proxy_set_header X-Forwarded-For $http_x_forwarded_for;
proxy_set_header X-Forwarded-Proto $http_x_forwarded_proto;
proxy_http_version 1.1;
proxy_set_header Connection "";
proxy_buffering off;
proxy_read_timeout 3600s;
proxy_send_timeout 3600s;
